package com.kennedy.wallet.service;
import com.kennedy.wallet.domain.*; import com.kennedy.wallet.repository.*; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.nio.charset.StandardCharsets; import java.security.MessageDigest; import java.security.SecureRandom; import java.time.Instant; import java.time.temporal.ChronoUnit; import java.util.Base64;
@Service public class AuthService {
 private final UserRepository users;private final AccountRepository accounts;private final RefreshTokenRepository tokens;private final PasswordEncoder encoder;private final JwtService jwt;private final FraudService fraud;private final AuditService audit;private static final String DUMMY="$2a$12$LQv3c1yqBWVHxkd0LHAkCOYz6e0rUj7Aqf3gjVwTvYpXc8t4jUy2S";
 public AuthService(UserRepository u,AccountRepository a,RefreshTokenRepository t,PasswordEncoder e,JwtService j,FraudService f,AuditService audit){users=u;accounts=a;tokens=t;encoder=e;jwt=j;fraud=f;this.audit=audit;}
 @Transactional public User register(String phone,String password){String normalized=PhoneNumbers.normalize(phone);checkPassword(password);if(users.findByPhone(normalized).isPresent())throw new IllegalArgumentException("Phone already registered");User user=users.save(new User(normalized,encoder.encode(passwordForBcrypt(password))));accounts.save(new Account(user));audit.record(user.getId(),"USER_REGISTERED",java.util.Map.of());return user;}
 @Transactional(noRollbackFor=InvalidCredentialsException.class) public TokenPair login(String phone,String password){String normalized=PhoneNumbers.normalize(phone);User user=users.findByPhone(normalized).orElse(null);boolean matches=encoder.matches(passwordForBcrypt(password),user==null?DUMMY:user.getPasswordHash());Instant now=Instant.now();if(user==null||!matches||!user.isEnabled()||(user.getLockedUntil()!=null&&user.getLockedUntil().isAfter(now))){if(user!=null){user.failedLogin(now.plus(15,ChronoUnit.MINUTES));audit.record(user.getId(),"LOGIN_FAILED",java.util.Map.of("attempts",user.getFailedLoginAttempts()));if(user.getLockedUntil()!=null&&user.getLockedUntil().isAfter(now)){audit.record(user.getId(),"ACCOUNT_LOCKED",java.util.Map.of("lockedUntil",user.getLockedUntil().toString()));}if(fraud.evaluateFailedLogin(user).outcome()==FraudService.Outcome.FLAG)audit.record(user.getId(),"FRAUD_FLAG",java.util.Map.of("signal","REPEATED_FAILED_LOGIN"));}else audit.record(null,"LOGIN_FAILED",java.util.Map.of("reason","UNKNOWN_PHONE"));throw new InvalidCredentialsException();}user.successfulLogin();audit.record(user.getId(),"LOGIN_SUCCEEDED",java.util.Map.of());return issuePair(user);}
 @Transactional(noRollbackFor=RefreshReuseException.class) public TokenPair refresh(String raw){String hash=hash(raw);RefreshToken old=tokens.findByTokenHash(hash).orElseThrow(()->new IllegalArgumentException("Invalid refresh token"));if(old.getRevokedAt()!=null){tokens.findAll().stream().filter(x->x.getUser().getId().equals(old.getUser().getId())&&x.getRevokedAt()==null).forEach(x->x.revoke(null));audit.record(old.getUser().getId(),"REFRESH_REUSE_DETECTED",java.util.Map.of());throw new RefreshReuseException();}if(old.getExpiresAt().isBefore(Instant.now())||!old.getUser().isEnabled()||(old.getUser().getLockedUntil()!=null&&old.getUser().getLockedUntil().isAfter(Instant.now())))throw new IllegalArgumentException("Invalid refresh token");TokenPair pair=issuePair(old.getUser());old.revoke(hash(pair.refreshToken()));audit.record(old.getUser().getId(),"TOKEN_REFRESHED",java.util.Map.of());return pair;}
 @Transactional public void logout(String raw){tokens.findByTokenHash(hash(raw)).ifPresent(t->{t.revoke(null);audit.record(t.getUser().getId(),"LOGOUT",java.util.Map.of());});}
 private TokenPair issuePair(User user){byte[] bytes=new byte[48];new SecureRandom().nextBytes(bytes);String raw=Base64.getUrlEncoder().withoutPadding().encodeToString(bytes);tokens.save(new RefreshToken(user,hash(raw),Instant.now().plus(30,ChronoUnit.DAYS)));return new TokenPair(jwt.issue(user),raw);}
 private String hash(String x){try{return java.util.HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(x.getBytes(StandardCharsets.UTF_8)));}catch(Exception e){throw new IllegalStateException(e);}}
 private String passwordForBcrypt(String password){try{return "wallet-v1:"+Base64.getUrlEncoder().withoutPadding().encodeToString(MessageDigest.getInstance("SHA-256").digest(password.getBytes(StandardCharsets.UTF_8)));}catch(Exception e){throw new IllegalStateException(e);}}
 private void checkPassword(String p){if(p==null||p.length()<8||p.length()>72)throw new IllegalArgumentException("Password must contain 8 to 72 characters");}
 public record TokenPair(String accessToken,String refreshToken){}
 public static class RefreshReuseException extends IllegalArgumentException {public RefreshReuseException(){super("Invalid refresh token");}}
 public static class InvalidCredentialsException extends IllegalArgumentException {public InvalidCredentialsException(){super("Invalid credentials");}}
}
